<script>document.querySelectorAll('[data-price]').forEach(input=>input.addEventListener('input',updateTotal));function updateTotal(){let cents=0;document.querySelectorAll('[data-price]').forEach(input=>{const quantity=Number(input.value),minimum=Number(input.dataset.minimum);const mode=input.dataset.packaging;let error=quantity>0&&quantity<minimum?'Минимальный заказ — '+minimum+' шт.':'';if(!error&&quantity>0&&mode==='mixed'&&!Array.from({length:Math.min(Math.floor(quantity/3),4)+1},(_,i)=>i).some(packs=>(quantity-3*packs)%5===0))error='Количество должно складываться из упаковок по 3 и 5 шт.';if(!error&&quantity>0&&mode==='pair'&&quantity%2!==0)error='Только чётное количество';input.setCustomValidity(error);if(Number.isSafeInteger(quantity)&&quantity>0)cents+=quantity*Number(input.dataset.price)});document.getElementById('live-total').textContent=(Math.floor(cents/100)).toLocaleString('ru-RU')+','+String(cents%100).padStart(2,'0')+' ₽'}updateTotal()</script>
